#include <bits/stdc++.h>
using namespace std;

int main() {
    int x, top = 0;
    cin >> x;

    vector<vector<int>> m(x, vector<int>(x));

    for (int j = 0; j < x; j++) {
        for (int k = 0; k < x; k++) {
            cin >> m[j][k];
        }
    }

    for (int i = 0; i < x; i++) {
        top += m[i][i];
    }

    for (int i = x - 1; i >= 0; i--) {
        top += m[i][x - 1 - i];
    }

    for (int h = 0; h < x; h++) {
        top += m[h][(x - 1) / 2];
    }

    for (int h = 0; h < x; h++) {
        top += m[(x - 1) / 2][h];
    }

    top -= 3 * m[(x - 1) / 2][(x - 1) / 2];

    cout << top;
    return 0;
}

